import type { LogRecord } from '@opentelemetry/api-logs';
import { SeverityNumber } from '@opentelemetry/api-logs';
import { InstrumentationBase } from '@opentelemetry/browser-api';
import { getElementCSSSelector } from '#utils';
import { version } from '../../package.json' with { type: 'json' };
import {
  ATTR_CSS_SELECTOR,
  ATTR_MOUSE_EVENT_BUTTON,
  ATTR_PAGE_X,
  ATTR_PAGE_Y,
  ATTR_TAG_NAME,
  ATTR_TAGS,
  CLICK_EVENT_NAME,
} from './semconv.ts';
import type {
  AutoCapturedUserAction,
  MouseButton,
  UserActionInstrumentationConfig,
} from './types.ts';

const DEFAULT_AUTO_CAPTURED_ACTIONS: AutoCapturedUserAction[] = ['click'];
const OTEL_ELEMENT_ATTRIBUTE_PREFIX = 'data-otel-';

/**
 * This class automatically instruments different User Actions within the browser.
 */
export class UserActionInstrumentation extends InstrumentationBase<UserActionInstrumentationConfig> {
  private _onClickHandler: ((event: MouseEvent) => void) | undefined;

  constructor(config: UserActionInstrumentationConfig = {}) {
    super(
      '@opentelemetry/browser-instrumentation/user-action',
      version,
      config,
    );
  }

  private _getMouseButtonFromMouseEvent(
    event: MouseEvent,
  ): MouseButton | undefined {
    switch (event.button) {
      case 0:
        return 'left';
      case 1:
        return 'middle';
      case 2:
        return 'right';
      default:
        return undefined;
    }
  }

  private onClick(event: MouseEvent) {
    // Use one event per button, including when both contextmenu and auxclick fire.
    if (
      (event.type === 'click' && event.button !== 0) ||
      (event.type === 'auxclick' && event.button !== 1) ||
      (event.type === 'contextmenu' && event.button !== 2)
    ) {
      return;
    }

    // Back, forward and other extra buttons are not clicks we report.
    const button = this._getMouseButtonFromMouseEvent(event);
    if (!button) {
      return;
    }

    const element = event.target;

    if (!(element instanceof HTMLElement)) {
      return;
    }

    if (element.hasAttribute('disabled')) {
      return;
    }

    const cssSelector = getElementCSSSelector(element, {
      useIdForTargetElement: true,
      useIdForAncestors: true,
    });
    const otelPrefixedAttributes: Record<string, string> = {};

    // Grab all the attributes in the element that start with data-otel-*
    for (const attr of element.attributes) {
      if (attr.name.startsWith(OTEL_ELEMENT_ATTRIBUTE_PREFIX)) {
        otelPrefixedAttributes[
          attr.name.slice(OTEL_ELEMENT_ATTRIBUTE_PREFIX.length)
        ] = attr.value;
      }
    }

    const logRecord: LogRecord = {
      severityNumber: SeverityNumber.INFO,
      eventName: CLICK_EVENT_NAME,
      attributes: {
        [ATTR_PAGE_X]: event.pageX,
        [ATTR_PAGE_Y]: event.pageY,
        [ATTR_TAG_NAME]: element.tagName,
        [ATTR_TAGS]: otelPrefixedAttributes,
        [ATTR_MOUSE_EVENT_BUTTON]: button,
        [ATTR_CSS_SELECTOR]: cssSelector,
      },
    };

    this._applyCustomLogRecordData(logRecord);

    this.logger.emit(logRecord);
  }

  private _hasWarnedApplyCustomLogRecordData = false;

  private _applyCustomLogRecordData(logRecord: LogRecord) {
    const applyCustomLogRecordData = this._config.applyCustomLogRecordData;
    if (applyCustomLogRecordData) {
      if (!this._hasWarnedApplyCustomLogRecordData) {
        this._hasWarnedApplyCustomLogRecordData = true;
        this._diag.warn(
          'applyCustomLogRecordData is deprecated. Use a custom LogRecordProcessor registered with LoggerProvider instead.',
        );
      }
      this._safeExecute('applyCustomLogRecordData hook failed', () =>
        applyCustomLogRecordData(logRecord),
      );
    }
  }

  protected override _onEnable(): void {
    const autoCapturedActions =
      this._config.autoCapturedActions ?? DEFAULT_AUTO_CAPTURED_ACTIONS;

    if (autoCapturedActions.includes('click')) {
      // A throw in a listener is reported as an uncaught page error.
      this._onClickHandler = (event) =>
        this._safeExecute('failed to record a click', () =>
          this.onClick(event),
        );
      document.addEventListener('click', this._onClickHandler, true);
      // Native context menus can consume mouseup before auxclick fires.
      document.addEventListener('auxclick', this._onClickHandler, true);
      document.addEventListener('contextmenu', this._onClickHandler, true);
    }
  }

  protected override _onDisable(): void {
    if (this._onClickHandler) {
      document.removeEventListener('click', this._onClickHandler, true);
      document.removeEventListener('auxclick', this._onClickHandler, true);
      document.removeEventListener('contextmenu', this._onClickHandler, true);
      this._onClickHandler = undefined;
    }
  }
}
